// Generate a mix of baseline + recent gap topic queries
const stats = $input.first().json;

// Baseline pharma/cyber questions to test RAG quality
const baselineQueries = [
  'What are the latest FDA drug approvals?',
  'What ransomware groups target pharmaceutical companies?',
  'What is GLP-1 and its role in obesity treatment?',
  'How does Dell PowerProtect Cyber Recovery work?',
  'What are the main cybersecurity threats to pharma manufacturing?',
  'What is CRISPR gene therapy and recent approvals?',
  'How does antibody drug conjugate ADC therapy work?',
  'What are the NIS2 directive requirements for pharma?',
  'What shadow AI risks exist in pharmaceutical companies?',
  'What are the main patient data breach trends on the darknet?'
];

// Shuffle and pick 5 baseline queries
const shuffled = baselineQueries.sort(() => Math.random() - 0.5);
const selected = shuffled.slice(0, 5);

return selected.map((q, i) => ({
  json: {
    query: q,
    query_index: i,
    query_type: 'baseline',
    total_chunks: stats.totalChunks || 0,
    total_sources: stats.sources ? stats.sources.length : 0
  }
}));

// Parse quality scores and build per-query results
const items = $input.all();
const queryItems = $('Generate Test Queries').all();
const ragItems = $('Query RAG Pipeline').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const query = queryItems[i] ? queryItems[i].json : {};
  const ragResponse = ragItems[i] ? ragItems[i].json : {};
  const ollamaResp = String(item.json.response || '');

  let score = 5;
  let hasSources = false;
  let isHallucination = false;
  let reason = 'parse_failed';

  try {
    const match = ollamaResp.match(/\{[\s\S]*?\}/);
    if (match) {
      const parsed = JSON.parse(match[0]);
      score = parsed.score || 5;
      hasSources = parsed.has_sources || false;
      isHallucination = parsed.is_hallucination || false;
      reason = parsed.reason || 'unknown';
    }
  } catch (e) {
    reason = 'json_parse_error';
  }

  results.push({
    json: {
      query: query.query || 'unknown',
      query_type: query.query_type || 'baseline',
      score: score,
      has_sources: hasSources,
      is_hallucination: isHallucination,
      reason: reason,
      response_length: (ragResponse.response || ragResponse.answer || '').length,
      latency_ms: ragResponse.latency_ms || 0
    }
  });
}

return results;

// Aggregate all quality scores into a health report
const queryResults = $('Parse Quality Scores').all();
const kbStats = $('Get KB Stats').first().json;
const dashMetrics = $('Get Dashboard Metrics').first().json;

const scores = queryResults.map(r => r.json.score);
const avgScore = scores.length > 0 ? scores.reduce((a, b) => a + b, 0) / scores.length : 0;
const minScore = scores.length > 0 ? Math.min(...scores) : 0;
const maxScore = scores.length > 0 ? Math.max(...scores) : 0;

const hallucinations = queryResults.filter(r => r.json.is_hallucination).length;
const withSources = queryResults.filter(r => r.json.has_sources).length;
const lowScoreQueries = queryResults.filter(r => r.json.score < 5).map(r => r.json);

// Determine overall health
let health = 'healthy';
if (avgScore < 5) health = 'unhealthy';
else if (avgScore < 7 || hallucinations > 1) health = 'degraded';

const report = {
  timestamp: new Date().toISOString(),
  health: health,
  knowledge_base: {
    total_chunks: kbStats.totalChunks || 0,
    sources_count: kbStats.sources ? kbStats.sources.length : 0
  },
  quality_scores: {
    avg_score: Math.round(avgScore * 10) / 10,
    min_score: minScore,
    max_score: maxScore,
    queries_tested: scores.length,
    with_sources: withSources,
    hallucinations_detected: hallucinations
  },
  low_score_queries: lowScoreQueries,
  gap_stats: {
    total_questions: dashMetrics.total_questions || 0,
    total_gaps: dashMetrics.total_gaps || 0,
    gap_rate: dashMetrics.total_questions > 0 ? Math.round((dashMetrics.total_gaps / dashMetrics.total_questions) * 100) : 0
  }
};

console.log('[KB Health] ' + JSON.stringify(report));

return [{ json: report }];

// Generate alert with actionable recommendations
const report = $('Build Health Report').first().json;

const alerts = [];

if (report.quality_scores.avg_score < 5) {
  alerts.push('CRITICAL: Average RAG quality score is ' + report.quality_scores.avg_score + '/10. Knowledge base may need re-indexing.');
}

if (report.quality_scores.hallucinations_detected > 0) {
  alerts.push('WARNING: ' + report.quality_scores.hallucinations_detected + ' hallucination(s) detected in ' + report.quality_scores.queries_tested + ' test queries.');
}

if (report.gap_stats.gap_rate > 30) {
  alerts.push('WARNING: Gap detection rate is ' + report.gap_stats.gap_rate + '%. Knowledge base coverage may be insufficient.');
}

for (const lq of report.low_score_queries || []) {
  alerts.push('LOW SCORE (' + lq.score + '/10): "' + lq.query + '" - ' + lq.reason);
}

const alertReport = {
  timestamp: report.timestamp,
  health: report.health,
  alert_count: alerts.length,
  alerts: alerts,
  recommendation: report.quality_scores.avg_score < 5 
    ? 'Run full re-index: POST /api/knowledge/reindex' 
    : 'Review low-scoring topics and add targeted knowledge documents'
};

console.log('[KB ALERT] ' + JSON.stringify(alertReport));

return [{ json: alertReport }];

// All healthy — log and done
const report = $('Build Health Report').first().json;
console.log('[KB Health] All healthy. Avg score: ' + report.quality_scores.avg_score + '/10, ' + report.knowledge_base.total_chunks + ' chunks.');
return [{ json: { status: 'healthy', message: 'No action needed', avg_score: report.quality_scores.avg_score } }];
